<?php $statusLabels=['scheduled'=>'Programada','sending'=>'En curso','paused'=>'Pausada','completed'=>'Completada']; $recipientLabels=['queued'=>'Pendiente','sending'=>'Procesando','sent'=>'Enviado','failed'=>'Fallido','unsubscribed'=>'Desuscrito']; ?>
<div class="admin-page-heading"><div><span class="admin-eyebrow">Campaña #<?= (int) $campaign['id'] ?></span><h1><?= e($campaign['name']) ?></h1><p><?= e($campaign['subject']) ?></p></div><div class="admin-heading-actions"><a class="btn admin-secondary-btn" href="<?= url('/admin/email-marketing') ?>">Volver</a><?php if (\App\Core\Auth::can('marketing.manage') && in_array($campaign['status'],['scheduled','sending','paused'],true)): ?><form method="post" action="<?= url('/admin/email-marketing/estado') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $campaign['id'] ?>"><button class="btn <?= $campaign['status']==='paused' ? 'admin-primary-btn' : 'admin-secondary-btn' ?>" type="submit"><?= $campaign['status']==='paused' ? 'Reanudar' : 'Pausar' ?></button></form><?php endif; ?></div></div>
<div class="row g-4 admin-metrics mb-4"><div class="col-md-3"><article><div><span>Total</span><strong><?= (int) $campaign['total_recipients'] ?></strong><small>Destinatarios únicos</small></div></article></div><div class="col-md-3"><article><div><span>Enviados</span><strong><?= (int) $campaign['sent_count'] ?></strong><small>Confirmados por servidor</small></div></article></div><div class="col-md-3"><article><div><span>Fallidos</span><strong><?= (int) $campaign['failed_count'] ?></strong><small>Después de 3 intentos</small></div></article></div><div class="col-md-3"><article><div><span>Estado</span><strong class="marketing-status-text"><?= e($statusLabels[$campaign['status']] ?? $campaign['status']) ?></strong><small>Intervalo: 10 minutos</small></div></article></div></div>
<section class="admin-panel"><div class="admin-panel__header"><div><span class="admin-eyebrow">Trazabilidad individual</span><h2>Destinatarios</h2></div></div><div class="table-responsive"><table class="table admin-table align-middle mb-0"><thead><tr><th>Destinatario</th><th>Programado</th><th>Enviado</th><th>Intentos</th><th>Estado</th></tr></thead><tbody><?php foreach ($campaign['recipients'] as $recipient): ?><tr><td><strong><?= e($recipient['name'] ?: $recipient['email']) ?></strong><small class="d-block"><?= e($recipient['email']) ?><?= $recipient['company'] ? ' · '.e($recipient['company']) : '' ?></small><?php if ($recipient['last_error']): ?><small class="d-block text-danger"><?= e($recipient['last_error']) ?></small><?php endif; ?></td><td><?= e(date('d/m/Y H:i',strtotime($recipient['scheduled_at']))) ?></td><td><?= $recipient['sent_at'] ? e(date('d/m/Y H:i',strtotime($recipient['sent_at']))) : '—' ?></td><td><?= (int) $recipient['attempts'] ?></td><td><span class="status-badge status-<?= e($recipient['status']) ?>"><?= e($recipientLabels[$recipient['status']] ?? $recipient['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section>
